const incoming = $input.first()?.json || {};
const payload = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const backendBase = String($env.BACKEND_BASE_URL || '').replace(/\/+$/, '');
const backendToken = String($env.BACKEND_API_TOKEN || '').trim();
if (!backendBase || !backendToken) throw new Error('Backend routing credentials are required for Gelato print assembly');
if (!payload.submissionId || !payload.claimToken) throw new Error('Gelato print assembly requires the W1.1 submission claim');
let result;
try {
result = await this.helpers.httpRequest({
  method: 'POST',
  url: backendBase + '/api/internal/w4/build-gelato-sibling-print-pdf',
  headers: { Authorization: 'Bearer ' + backendToken, 'Content-Type': 'application/json' },
  body: payload,
  json: true,
  timeout: 120000,
});
if (!result || result.success !== true) throw new Error('Gelato print assembly did not return success');
} catch {
  throw new Error('Gelato PDF assembly failed; expired pre-send claims require server recovery');
}
return [{ json: { status: 'assembled', ...result, submissionId: payload.submissionId, claimToken: payload.claimToken, executionId: String($execution.id), mode: 'siblings' } }];

const incoming = $input.first().json;
const identity = { submissionId: incoming.submissionId, claimToken: incoming.claimToken, executionId: incoming.executionId, mode: incoming.mode };
const backendBase = String($env.BACKEND_BASE_URL || '').replace(/\/+$/, '');
const backendToken = String($env.BACKEND_API_TOKEN || '').trim();
if (!backendBase || !backendToken) throw new Error('Backend credentials are required');
let result;
try {
  result = await this.helpers.httpRequest({ method: 'POST', url: backendBase + '/api/internal/w4/quote-gelato-submission',
    headers: { Authorization: 'Bearer ' + backendToken, 'Content-Type': 'application/json' }, body: identity, json: true, timeout: 120000 });
  if (!result || result.success !== true) throw new Error('Gelato transition was not confirmed');
} catch {
  throw new Error('Gelato transition failed; inspect saved submission before retrying');
}
return [{ json: { ...identity, ...result } }];

